a diferir ese pago. Binding pendiente."}],"hechos":["s22f04_presenta_fecha_primera_cuota","s22f04_fecha_no_autorizada","s22f04_campo_nulo","s22f04_mensaje_nulo_invalido"],"paquete":{"tipo":"NUEVA","codigo":"S22F-C04","clave":"s22f_legacy_158","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Origen de fecha contractual de primera cuota","descripcion":"Al presentar fecha de primera cuota de oferta en cuotas BLOQUEAR fecha calculada o inventada por LF en lugar de campo autorizado por aliado B2B. Si campo es nulo, presentar A coordinar con el aliado, no inferir fecha. No cambia exigencia de pago inicial en checkout de S22B-C03; la fecha presentada no autoriza diferir ese pago. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/158","solicitante":"Cristhian / Claude S22-F 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22f04_presenta_fecha_primera_cuota"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22f04_fecha_no_autorizada"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22f04_campo_nulo"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22f04_mensaje_nulo_invalido"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":false,"s22f04_mensaje_nulo_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":true,"s22f04_campo_nulo":false,"s22f04_mensaje_nulo_invalido":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":false,"s22f04_fecha_no_autorizada":true,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":true},"esperado":false}]},"hash":"2b4e9c6829ead5cbc5b04d039ef48572a7543f60760e4ba94e98cbdb3b8cf716","hash_paquete":"7a8b40464867d0ac28e6fd5782bf12d65abf313f0ebda03e8cf3c479ee23bcb9","hash_evaluado":"2b4e9c6829","hash_paquete_10":"7a8b404648","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"relacionada con S22B-C03, declarado"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','PR #4761 / Claude 2026-11-25 01:04 Lima / '||cd||' / hash_paquete_10='||(p->>'hash_paquete_10'));
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22F_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22F_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22F_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>4 OR vectors<>21 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22F_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22F_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 01:04 Lima'),h,'GPT / Claude S22-F independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22F_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 cd:='S21-C04'; lid:=44;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22F_DIRECT_ATTESTATION_MISSING %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
 diff:='S21-C04 exige validación server-side previa del formato numérico RENIEC canónico y bloquea consulta de unicidad con formato inválido; no fija longitud literal.'; residual:='Falta fijar el literal de 8 dígitos solo numéricos del formato RENIEC canónico';
 IF length(diff)<30 OR length(residual)<15 THEN RAISE EXCEPTION 'S22F_DIRECT_CONTRACT %',lid; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 01:04 Lima'),direct_hash,'GPT / Claude S22-F independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22F_SOURCE_MISSING %',lid; END IF;
 cd:='S11-C02'; lid:=101;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22F_DIRECT_ATTESTATION_MISSING %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
 diff:='S11-C02 cubre Home, S9-C06 onboarding, S15-C06 pagos y S12-C09 B2B; no lectura directa DOM.'; residual:='Falta acreditar cobertura universal para eventos de todas las superficies restantes y todos los tags autorizados.';
 IF length(diff)<30 OR length(residual)<15 THEN RAISE EXCEPTION 'S22F_DIRECT_CONTRACT %',lid; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 01:04 Lima'),direct_hash,'GPT / Claude S22-F independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22F_SOURCE_MISSING %',lid; END IF;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>9 OR after_replaced<>before_replaced+5) THEN RAISE EXCEPTION 'S22F_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22F_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22F_PASS 4 JUICIOS 4 AUTO 21 VECTORES links=% replaced=% DPIG03=0',links,after_replaced;
END $s22$;
COMMIT;
